def transform(grid):
    h,w=len(grid),len(grid[0])
    p4=[(r,c) for r in range(h) for c in range(w) if grid[r][c]==4]
    p6=[(r,c) for r in range(h) for c in range(w) if grid[r][c]==6]
    out=[row[:] for row in grid]
    for r,c in p6: out[r][c]=0
    # Source and marker indicate symmetry axis along the line joining their centers;
    # reflect the source across its nearest boundary on the marker-facing side.
    r4=sum(r for r,c in p4)/len(p4); c4=sum(c for r,c in p4)/len(p4)
    r6=sum(r for r,c in p6)/len(p6); c6=sum(c for r,c in p6)/len(p6)
    if abs(r6-r4)>=abs(c6-c4):
        if r6>r4:
            edge=max(r for r,c in p4)
            for r,c in p4:
                rr=2*edge-r+1
                if 0<=rr<h: out[rr][c]=4
        else:
            edge=min(r for r,c in p4)
            for r,c in p4:
                rr=2*edge-r-1
                if 0<=rr<h: out[rr][c]=4
    else:
        if c6>c4:
            edge=max(c for r,c in p4)
            for r,c in p4:
                cc=2*edge-c+1
                if 0<=cc<w: out[r][cc]=4
        else:
            edge=min(c for r,c in p4)
            for r,c in p4:
                cc=2*edge-c-1
                if 0<=cc<w: out[r][cc]=4
    return out
